'use strict';

const App = { currentUser:null, state:{serverOnline:true,internetOnline:navigator.onLine} };
const $ = (s,r=document)=>r.querySelector(s); const $$=(s,r=document)=>Array.from(r.querySelectorAll(s));
function escapeHTML(v){return String(v??'').replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]));}
function money(v){return Number(v||0).toLocaleString('ar-YE',{minimumFractionDigits:2,maximumFractionDigits:2});}
function date(v){return v?new Date(v).toLocaleString('ar-YE'): '-';}
function csvEscape(v){return `"${String(v??'').replace(/"/g,'""')}"`;}
function exportTable(table,title='export'){const rows=$$('tr',table).map(tr=>$$('th,td',tr).map(x=>csvEscape(x.textContent.trim())));const blob=new Blob(['\ufeff'+rows.map(r=>r.join(',')).join('\n')],{type:'text/csv;charset=utf-8'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=`${title}.csv`;a.click();URL.revokeObjectURL(a.href);}
function printHTML(title,html){const w=window.open('','_blank','width=1000,height=800');if(!w){showToast('اسمح بالنوافذ المنبثقة للطباعة','error');return;}w.document.write(`<!doctype html><html lang="ar" dir="rtl"><head><meta charset="utf-8"><title>${escapeHTML(title)}</title><style>body{font-family:Arial;padding:24px;direction:rtl}table{width:100%;border-collapse:collapse}th,td{border:1px solid #ddd;padding:8px}h1{margin-bottom:20px}</style></head><body><h1>${escapeHTML(title)}</h1>${html}</body></html>`);w.document.close();w.focus();setTimeout(()=>{w.print();w.close()},250);}

async function apiFetch(path,options={}){const res=await fetch(`/api${path}`,{...options,credentials:'include',headers:{'Content-Type':'application/json',...(options.headers||{})}});if(res.status===401&&!path.startsWith('/auth/')){const r=await fetch('/api/auth/refresh',{method:'POST',credentials:'include'});if(r.ok)return apiFetch(path,options);showLoginView();throw new Error('انتهت الجلسة');}const data=await res.json().catch(()=>({}));if(!res.ok)throw new Error(data.error||data.message||`خطأ HTTP ${res.status}`);return data;}
window.apiFetch=apiFetch;
const AudioFeedback=(()=>{let ctx=null;const beep=(f,d,t='sine')=>{if(localStorage.getItem('sound_enabled')==='false')return;try{ctx ||= new(window.AudioContext||window.webkitAudioContext)();const o=ctx.createOscillator(),g=ctx.createGain();o.type=t;o.frequency.value=f;g.gain.value=Number(localStorage.getItem('sound_volume')||.2);o.connect(g);g.connect(ctx.destination);o.start();o.stop(ctx.currentTime+d/1000)}catch(e){}};return{success:()=>beep(880,120),error:()=>beep(220,160,'square'),warning:()=>beep(440,180,'triangle'),scanSuccess:()=>beep(1200,80)}})();
function showToast(message,type='success'){const c=$('#toastContainer');if(!c)return;const t=document.createElement('div');t.className=`toast toast--${type}`;t.textContent=message;c.appendChild(t);({success:AudioFeedback.success,error:AudioFeedback.error,warning:AudioFeedback.warning}[type]||(()=>{}))();setTimeout(()=>t.remove(),3500)}window.showToast=showToast;
function showLoginView(){$('#loginView').classList.remove('hidden');$('#mainTabbar').classList.add('hidden');['posView','dashboardView','genericView'].forEach(id=>$('#'+id)?.classList.add('hidden'));}
function applyRoleBasedUI(u){$$('.tab').forEach(t=>{let ok=true;if(t.dataset.requires&&u.role!=='admin'&&!u[t.dataset.requires])ok=false;if(t.dataset.role&&!t.dataset.role.split(',').includes(u.role))ok=false;t.style.display=ok?'':'none';});}
async function handleLogin(e){e.preventDefault();const err=$('#loginError');err.textContent='';try{const d=await apiFetch('/auth/login',{method:'POST',body:JSON.stringify({username:$('#loginUsername').value.trim(),password:$('#loginPassword').value,totpCode:$('#loginTotp').value.trim()||undefined})});if(d.requiresTwoFactor){$('#totpField').classList.remove('hidden');err.textContent='أدخل رمز التحقق الثنائي';return;}App.currentUser=d.user;$('#userNameLabel').textContent=d.user.fullName;$('#loginView').classList.add('hidden');$('#mainTabbar').classList.remove('hidden');applyRoleBasedUI(d.user);switchView('pos');startStatusPolling()}catch(e){err.textContent=e.message;AudioFeedback.error()}}
async function handleLogout(){try{await apiFetch('/auth/logout',{method:'POST'})}catch(e){}location.reload()}

function switchView(view){$$('.tab').forEach(t=>t.classList.toggle('active',t.dataset.view===view));$('#posView').classList.toggle('hidden',view!=='pos');$('#dashboardView').classList.toggle('hidden',view!=='dashboard');$('#genericView').classList.toggle('hidden',['pos','dashboard'].includes(view));if(view==='dashboard')window.Dashboard?.load();if(view==='pos')window.POS?.refreshTopProducts();if(!['pos','dashboard'].includes(view))loadGenericView(view);}
window.switchView=switchView;

function shell(title,actions=''){return `<div class="page-wrap"><h2 class="page-title">${escapeHTML(title)}</h2><div class="toolbar">${actions}</div><div id="viewBody"></div></div>`}
function toolbar(searchId,addLabel='إضافة'){return `<input id="${searchId}" class="search-input" placeholder="بحث..."/><button class="btn btn--primary" id="addBtn">➕ ${addLabel}</button><button class="btn btn--outline" id="refreshBtn">🔄 تحديث</button><button class="btn btn--outline" id="exportBtn">📥 تصدير CSV</button><button class="btn btn--outline" id="printBtn">🖨️ طباعة</button>`}
function setBody(html){$('#viewBody').innerHTML=html}
function bindToolbar(searchId,rerender,title){$('#refreshBtn').onclick=rerender;$('#exportBtn').onclick=()=>{const t=$('#viewBody table');if(t)exportTable(t,title)};$('#printBtn').onclick=()=>{const b=$('#viewBody').innerHTML;printHTML(title,b)};if(searchId)$('#'+searchId).oninput=()=>rerender($('#'+searchId).value.trim());}
function openModal(title,html,onReady){const m=$('#drilldownModal'),b=$('#drilldownBody');m.classList.remove('hidden');b.innerHTML=`<div class="form-card modal-form"><h3>${escapeHTML(title)}</h3>${html}</div>`;onReady?.(b);}
function closeModal(){$('#drilldownModal').classList.add('hidden');}

async function loadGenericView(view){const c=$('#genericViewContent');c.innerHTML='<div class="empty-state">جاري التحميل...</div>';try{const map={products:renderProducts,customers:renderCustomers,suppliers:renderSuppliers,purchases:renderPurchases,inventory:renderInventory,invoices:renderInvoices,returns:renderReturns,reports:renderReports,shifts:renderShifts,expenses:renderExpenses,paymentMethods:renderPaymentMethods,accounting:renderAccounting,ledger:renderLedger,drawer:renderDrawer,settings:renderSettings};if(map[view])await map[view](c);else c.innerHTML='<div class="empty-state">التبويب غير معروف</div>'}catch(e){c.innerHTML=`<div class="empty-state danger-text">${escapeHTML(e.message)}</div>`}}

async function renderProducts(c,search=''){c.innerHTML=shell('المنتجات',toolbar('productSearch','إضافة منتج')+'<button class="btn btn--primary" id="smartSearchBtn">🧠 بحث ذكي عربي/يمني</button>');const body=$('#viewBody');const data=await apiFetch('/products?limit=200');let rows=data.products||[];const render=()=>{const q=$('#productSearch').value.trim().toLowerCase();const filtered=rows.filter(p=>!q||`${p.name} ${p.barcode||''}`.toLowerCase().includes(q));body.innerHTML=filtered.length?`<table class="data-table"><thead><tr><th>المنتج</th><th>الباركود</th><th>الوحدة</th><th>الكمية</th><th>التكلفة</th><th>البيع</th><th>الحالة</th><th>إجراءات</th></tr></thead><tbody>${filtered.map(p=>`<tr><td>${escapeHTML(p.name)}</td><td>${escapeHTML(p.barcode||'-')}</td><td>${escapeHTML(p.base_unit||'-')}</td><td>${money(p.base_quantity)}</td><td>${money(p.base_cost)}</td><td>${money(p.retail_price??p.base_cost)}</td><td>${p.base_quantity<=p.reorder_point?'<span class="pill danger-text">منخفض</span>':'<span class="pill">متوفر</span>'}</td><td class="action-cell"><button class="btn btn--outline action-btn" data-detail="${p.id}">👁 تفاصيل</button><button class="btn btn--primary action-btn" data-edit="${p.id}">✏️ تعديل</button><button class="btn btn--danger action-btn" data-del="${p.id}">🗑 تعطيل</button></td></tr>`).join('')}</tbody></table>`:'<div class="empty-state">لا توجد منتجات مطابقة.</div>';body.querySelectorAll('[data-edit]').forEach(b=>b.onclick=()=>productForm(rows.find(x=>x.id===b.dataset.edit)));body.querySelectorAll('[data-del]').forEach(b=>b.onclick=async()=>{if(!confirm('تعطيل المنتج؟'))return;try{await apiFetch('/products/'+b.dataset.del,{method:'DELETE'});showToast('تم تعطيل المنتج');render()}catch(e){showToast(e.message,'error')}});body.querySelectorAll('[data-detail]').forEach(b=>b.onclick=()=>productDetail(b.dataset.detail));};render();bindToolbar('productSearch',render,'المنتجات');$('#addBtn').onclick=()=>productForm(null);$('#smartSearchBtn').onclick=()=>smartProductSearch();}

async function smartProductSearch(){
  openModal('البحث الذكي العربي/اليمني',`<form id="smartForm"><label>اكتب اسم المنتج أو المرادف أو الباركود<input name="term" id="smartTerm" required placeholder="مثال: موية، بسباس، بطاطا، أو الباركود"></label><button class="btn btn--primary btn--block">🔎 بحث</button></form><div id="smartResults"></div>`,b=>{
    $('#smartForm',b).onsubmit=async e=>{e.preventDefault();try{const term=$('[name=term]',b).value.trim();const d=await apiFetch('/products/search-advanced',{method:'POST',body:JSON.stringify({term,limit:50})});$('#smartResults',b).innerHTML=d.products.length?`<table class="data-table"><thead><tr><th>المنتج</th><th>الباركود</th><th>الكمية</th><th>السعر</th><th>إجراء</th></tr></thead><tbody>${d.products.map(p=>`<tr><td>${escapeHTML(p.name)}</td><td>${escapeHTML(p.barcode||'-')}</td><td>${money(p.base_quantity)}</td><td>${money(p.retail_price||p.base_cost)}</td><td><button class="btn btn--success action-btn" data-add-smart="${p.id}">➕ إلى POS</button></td></tr>`).join('')}</tbody></table>`:'<div class="empty-state">لم يتم العثور على نتائج.</div>';$$('[data-add-smart]',b).forEach(btn=>btn.onclick=async()=>{try{const d2=await apiFetch('/products/'+btn.dataset.addSmart);closeModal();switchView('pos');window.POS?.addExternalProduct?.(d2.product,d2.units)}catch(err){showToast(err.message,'error')}})}catch(err){showToast(err.message,'error')}};
  });
}
async function productDetail(id){const d=await apiFetch('/products/'+id);openModal('تفاصيل المنتج',`<div class="stat-row"><div class="stat-card"><div>الاسم</div><div class="value">${escapeHTML(d.product.name)}</div></div><div class="stat-card"><div>الكمية</div><div class="value">${money(d.product.base_quantity)}</div></div><div class="stat-card"><div>التكلفة</div><div class="value">${money(d.product.base_cost)}</div></div></div><h4>الوحدات</h4><table class="data-table"><thead><tr><th>الوحدة</th><th>بيع</th><th>جملة</th></tr></thead><tbody>${(d.units||[]).map(u=>`<tr><td>${escapeHTML(u.unit_name)}</td><td>${money(u.retail_price)}</td><td>${money(u.wholesale_price)}</td></tr>`).join('')}</tbody></table><h4>مرادفات البحث</h4><p>${(d.aliases||[]).map(a=>`<span class="pill">${escapeHTML(a.alias)}</span>`).join(' ')||'لا يوجد'}</p>`)}
function productForm(p){const x=p||{};openModal(p?'تعديل المنتج':'إضافة منتج',`<form id="entityForm"><div class="form-grid"><label>الاسم<input name="name" required value="${escapeHTML(x.name)}"></label><label>الوحدة<input name="baseUnit" value="${escapeHTML(x.base_unit||'قطعة')}"></label><label>الباركود<input name="barcode" value="${escapeHTML(x.barcode||'')}"></label><label>التكلفة<input name="baseCost" type="number" step="0.01" value="${x.base_cost??0}"></label><label>سعر البيع<input name="retailPrice" type="number" step="0.01" value="${x.retail_price??0}"></label><label>سعر الجملة<input name="wholesalePrice" type="number" step="0.01" value="${x.wholesale_price??0}"></label><label>حد الجملة<input name="wholesaleMinQty" type="number" step="0.001" value="${x.wholesale_min_qty??0}"></label><label>حد إعادة الطلب<input name="reorderPoint" type="number" step="0.01" value="${x.reorder_point??0}"></label>${p?'':'<label>المخزون الافتتاحي<input name="openingQuantity" type="number" step="0.001" value="0"></label><label>رقم الدفعة<input name="batchNumber"></label><label>تاريخ الصلاحية<input name="expiryDate" type="date"></label>'}<label>مرادفات البحث<input name="aliases" placeholder="موية،مويه،ماء"></label><label style="grid-column:1/-1">الوصف<textarea name="description">${escapeHTML(x.description||'')}</textarea></label></div><button class="btn btn--success btn--block" type="submit">💾 حفظ المنتج</button></form>`,b=>{$('#entityForm',b).onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target);const body={name:f.get('name'),baseUnit:f.get('baseUnit')||'قطعة',barcode:f.get('barcode')||null,baseCost:Number(f.get('baseCost')||0),retailPrice:Number(f.get('retailPrice')||0),wholesalePrice:Number(f.get('wholesalePrice')||0),wholesaleMinQty:Number(f.get('wholesaleMinQty')||0),reorderPoint:Number(f.get('reorderPoint')||0),description:f.get('description')||'',aliases:String(f.get('aliases')||'').split(',').map(s=>s.trim()).filter(Boolean)};if(!p){body.openingQuantity=Number(f.get('openingQuantity')||0);body.batchNumber=f.get('batchNumber')||null;body.expiryDate=f.get('expiryDate')||null;}try{await apiFetch(p?'/products/'+p.id:'/products',{method:p?'PUT':'POST',body:JSON.stringify(body)});showToast(p?'تم تعديل المنتج':'تمت إضافة المنتج');closeModal();loadGenericView('products')}catch(err){showToast(err.message,'error')}}})}

async function renderCustomers(c){c.innerHTML=shell('العملاء',toolbar('customerSearch','إضافة عميل'));const data=await apiFetch('/customers?limit=200');const rows=data.customers||[];const render=()=>{const q=$('#customerSearch').value.trim().toLowerCase();const r=rows.filter(x=>`${x.name} ${x.phone||''}`.toLowerCase().includes(q));$('#viewBody').innerHTML=r.length?`<table class="data-table"><thead><tr><th>الاسم</th><th>الهاتف</th><th>النوع</th><th>الرصيد</th><th>حد الائتمان</th><th>إجراءات</th></tr></thead><tbody>${r.map(x=>`<tr><td>${escapeHTML(x.name)}</td><td>${escapeHTML(x.phone||'-')}</td><td>${escapeHTML(x.customer_type)}</td><td>${money(x.balance)}</td><td>${money(x.credit_limit)}</td><td class="action-cell"><button class="btn btn--outline action-btn" data-c="${x.id}">👁 تفاصيل</button><button class="btn btn--primary action-btn" data-e="${x.id}">✏️ تعديل</button><button class="btn btn--success action-btn" data-pay="${x.id}">💵 تسديد</button><button class="btn btn--danger action-btn" data-d="${x.id}">🗑 تعطيل</button></td></tr>`).join('')}</tbody></table>`:'<div class="empty-state">لا توجد نتائج.</div>';$$('[data-e]').forEach(b=>b.onclick=()=>customerForm(rows.find(x=>x.id===b.dataset.e)));$$('[data-d]').forEach(b=>b.onclick=async()=>{if(!confirm('تعطيل العميل؟'))return;try{await apiFetch('/customers/'+b.dataset.d,{method:'DELETE'});showToast('تم التعطيل');loadGenericView('customers')}catch(e){showToast(e.message,'error')}});$$('[data-pay]').forEach(b=>b.onclick=()=>customerPayment(rows.find(x=>x.id===b.dataset.pay)));$$('[data-c]').forEach(b=>b.onclick=()=>customerDetail(b.dataset.c));};render();bindToolbar('customerSearch',render,'العملاء');$('#addBtn').onclick=()=>customerForm(null);}
function customerForm(x){x=x||{};openModal(x.id?'تعديل العميل':'إضافة عميل',`<form id="entityForm"><div class="form-grid"><label>الاسم<input name="name" required value="${escapeHTML(x.name)}"></label><label>الهاتف<input name="phone" value="${escapeHTML(x.phone||'')}"></label><label>البريد<input name="email" type="email" value="${escapeHTML(x.email||'')}"></label><label>العنوان<input name="address" value="${escapeHTML(x.address||'')}"></label><label>النوع<select name="customerType"><option value="retail">تجزئة</option><option value="wholesale">جملة</option><option value="both">كلاهما</option></select></label><label>حد الائتمان<input name="creditLimit" type="number" step="0.01" value="${x.credit_limit??0}"></label></div><button class="btn btn--success btn--block">💾 حفظ</button></form>`,b=>{$('[name=customerType]',b).value=x.customer_type||'retail';$('#entityForm',b).onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target),body={name:f.get('name'),phone:f.get('phone'),email:f.get('email'),address:f.get('address'),customerType:f.get('customerType'),creditLimit:Number(f.get('creditLimit')||0)};try{await apiFetch(x.id?'/customers/'+x.id:'/customers',{method:x.id?'PUT':'POST',body:JSON.stringify(body)});showToast('تم الحفظ');closeModal();loadGenericView('customers')}catch(err){showToast(err.message,'error')}}})}
async function customerDetail(id){const d=await apiFetch('/customers/'+id);openModal('تفاصيل العميل',`<div class="stat-row"><div class="stat-card"><div>الاسم</div><div class="value">${escapeHTML(d.customer.name)}</div></div><div class="stat-card"><div>الرصيد</div><div class="value">${money(d.customer.balance)}</div></div><div class="stat-card"><div>المشتريات</div><div class="value">${money(d.customer.total_purchases)}</div></div></div>`)}
async function customerPayment(x){const pm=await apiFetch('/payment-methods');openModal('تسديد دين العميل',`<form id="entityForm"><div class="form-grid"><label>المبلغ<input name="amount" type="number" step="0.01" min="0.01" max="${x.balance||0}" required></label><label>وسيلة الدفع<select name="paymentMethodId">${pm.paymentMethods.filter(p=>p.type!=='credit').map(p=>`<option value="${p.id}">${escapeHTML(p.icon||'💳')} ${escapeHTML(p.name)}</option>`).join('')}</select></label><label>ملاحظات<input name="notes"></label></div><button class="btn btn--success btn--block">💵 تسجيل التسديد</button></form>`,b=>{$('#entityForm',b).onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target);try{await apiFetch(`/customers/${x.id}/payment`,{method:'POST',body:JSON.stringify({amount:Number(f.get('amount')),paymentMethodId:f.get('paymentMethodId'),notes:f.get('notes')})});showToast('تم تسجيل التسديد');closeModal();loadGenericView('customers')}catch(err){showToast(err.message,'error')}}})}

async function renderSuppliers(c){c.innerHTML=shell('الموردون',toolbar('supplierSearch','إضافة مورد'));const data=await apiFetch('/suppliers?limit=200');const rows=data.suppliers||[];const render=()=>{const q=$('#supplierSearch').value.trim().toLowerCase();const r=rows.filter(x=>`${x.name} ${x.phone||''}`.toLowerCase().includes(q));$('#viewBody').innerHTML=r.length?`<table class="data-table"><thead><tr><th>الاسم</th><th>الهاتف</th><th>البريد</th><th>الرصيد</th><th>إجراءات</th></tr></thead><tbody>${r.map(x=>`<tr><td>${escapeHTML(x.name)}</td><td>${escapeHTML(x.phone||'-')}</td><td>${escapeHTML(x.email||'-')}</td><td>${money(x.balance)}</td><td class="action-cell"><button class="btn btn--outline action-btn" data-e="${x.id}">✏️ تعديل</button><button class="btn btn--success action-btn" data-r="${x.id}">📥 استلام</button><button class="btn btn--danger action-btn" data-d="${x.id}">🗑 تعطيل</button></td></tr>`).join('')}</tbody></table>`:'<div class="empty-state">لا توجد نتائج.</div>';$$('[data-e]').forEach(b=>b.onclick=()=>supplierForm(rows.find(x=>x.id===b.dataset.e)));$$('[data-d]').forEach(b=>b.onclick=async()=>{if(!confirm('تعطيل المورد؟'))return;try{await apiFetch('/suppliers/'+b.dataset.d,{method:'DELETE'});showToast('تم التعطيل');loadGenericView('suppliers')}catch(e){showToast(e.message,'error')}});$$('[data-r]').forEach(b=>b.onclick=()=>receiveForm(rows.find(x=>x.id===b.dataset.r)));};render();bindToolbar('supplierSearch',render,'الموردون');$('#addBtn').onclick=()=>supplierForm(null);}
function supplierForm(x){x=x||{};openModal(x.id?'تعديل المورد':'إضافة مورد',`<form id="entityForm"><div class="form-grid"><label>الاسم<input name="name" required value="${escapeHTML(x.name)}"></label><label>الهاتف<input name="phone" value="${escapeHTML(x.phone||'')}"></label><label>البريد<input name="email" type="email" value="${escapeHTML(x.email||'')}"></label><label>العنوان<input name="address" value="${escapeHTML(x.address||'')}></label></div><button class="btn btn--success btn--block">💾 حفظ</button></form>`,b=>{$('#entityForm',b).onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target),body={name:f.get('name'),phone:f.get('phone'),email:f.get('email'),address:f.get('address')};try{await apiFetch(x.id?'/suppliers/'+x.id:'/suppliers',{method:x.id?'PUT':'POST',body:JSON.stringify(body)});showToast('تم الحفظ');closeModal();loadGenericView('suppliers')}catch(err){showToast(err.message,'error')}}})}
async function receiveForm(s){const products=(await apiFetch('/products?limit=200')).products||[];openModal('استلام بضاعة',`<form id="entityForm"><div class="form-grid"><label>المنتج<select name="productId">${products.map(p=>`<option value="${p.id}">${escapeHTML(p.name)}</option>`).join('')}</select></label><label>الكمية<input name="quantityReceived" type="number" min="0.001" step="0.001" required></label><label>سعر الشراء<input name="purchasePrice" type="number" min="0" step="0.01" required></label><label>رقم الدفعة<input name="batchNumber"></label><label>الصلاحية<input name="expiryDate" type="date"></label></div><button class="btn btn--success btn--block">📥 تسجيل الاستلام</button></form>`,b=>{$('#entityForm',b).onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target);try{await apiFetch('/suppliers/receive',{method:'POST',body:JSON.stringify({supplierId:s.id,productId:f.get('productId'),quantityReceived:Number(f.get('quantityReceived')),purchasePrice:Number(f.get('purchasePrice')),batchNumber:f.get('batchNumber')||null,expiryDate:f.get('expiryDate')||null,taxId:null})});showToast('تم استلام البضاعة');closeModal();loadGenericView('inventory')}catch(err){showToast(err.message,'error')}}})}

async function renderInventory(c){c.innerHTML=shell('المخزون',toolbar('inventorySearch','تسوية جرد'));const data=await apiFetch('/inventory');const rows=data.inventory||[];const render=()=>{const q=$('#inventorySearch').value.trim().toLowerCase();const r=rows.filter(x=>`${x.name}`.toLowerCase().includes(q));$('#viewBody').innerHTML=`<table class="data-table"><thead><tr><th>المنتج</th><th>الوحدة</th><th>الكمية</th><th>حد الطلب</th><th>قيمة المخزون</th><th>إجراءات</th></tr></thead><tbody>${r.map(x=>`<tr><td>${escapeHTML(x.name)}</td><td>${escapeHTML(x.base_unit)}</td><td>${money(x.base_quantity)}</td><td>${money(x.reorder_point)}</td><td>${money(x.inventory_value)}</td><td class="action-cell"><button class="btn btn--primary action-btn" data-a="${x.id}">⚖️ تسوية</button><button class="btn btn--outline action-btn" data-t="${x.id}">📜 الحركات</button><button class="btn btn--outline action-btn" data-b="${x.id}">📦 الدفعات</button></td></tr>`).join('')}</tbody></table>`;$$('[data-a]').forEach(b=>b.onclick=()=>adjustForm(rows.find(x=>x.id===b.dataset.a)));$$('[data-t]').forEach(b=>inventoryTransactions(b.dataset.t));$$('[data-b]').forEach(b=>inventoryBatches(b.dataset.b));};render();bindToolbar('inventorySearch',render,'المخزون');$('#addBtn').onclick=()=>adjustForm(null)}
function adjustForm(x){if(!x){showToast('اختر المنتج من زر التسوية داخل صف المنتج','warning');return}openModal('تسوية المخزون',`<form id="entityForm"><div class="form-grid"><label>المنتج<input disabled value="${escapeHTML(x.name)}"></label><label>الكمية الحالية<input disabled value="${x.base_quantity}"></label><label>الكمية الفعلية<input name="newQuantity" type="number" min="0" step="0.001" value="${x.base_quantity}" required></label><label style="grid-column:1/-1">ملاحظات<input name="notes"></label></div><button class="btn btn--success btn--block">💾 حفظ التسوية</button></form>`,b=>{$('#entityForm',b).onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target);try{await apiFetch('/inventory/adjust',{method:'POST',body:JSON.stringify({productId:x.id,newQuantity:Number(f.get('newQuantity')),notes:f.get('notes')})});showToast('تمت التسوية');closeModal();loadGenericView('inventory')}catch(err){showToast(err.message,'error')}}})}
async function inventoryTransactions(id){const d=await apiFetch('/inventory/transactions/'+id);openModal('حركات المخزون',`<table class="data-table"><thead><tr><th>التاريخ</th><th>النوع</th><th>الكمية</th><th>قبل</th><th>بعد</th></tr></thead><tbody>${(d.transactions||[]).map(x=>`<tr><td>${date(x.created_at)}</td><td>${escapeHTML(x.transaction_type)}</td><td>${money(x.base_quantity)}</td><td>${money(x.quantity_before)}</td><td>${money(x.quantity_after)}</td></tr>`).join('')}</tbody></table>`)}
async function inventoryBatches(id){const d=await apiFetch('/inventory/batches?productId='+encodeURIComponent(id));openModal('دفعات المخزون',`<table class="data-table"><thead><tr><th>الدفعة</th><th>الوارد</th><th>المتبقي</th><th>الصلاحية</th><th>التكلفة</th></tr></thead><tbody>${(d.batches||[]).map(x=>`<tr><td>${escapeHTML(x.batch_number||'-')}</td><td>${money(x.quantity_received)}</td><td>${money(x.quantity_remaining)}</td><td>${escapeHTML(x.expiry_date||'-')}</td><td>${money(x.purchase_price)}</td></tr>`).join('')}</tbody></table>`)}

async function renderInvoices(c){c.innerHTML=shell('الفواتير',toolbar('invoiceSearch','تحديث'));const data=await apiFetch('/pos/invoices?limit=200');const rows=data.invoices||[];const render=()=>{const q=$('#invoiceSearch').value.trim().toLowerCase();const r=rows.filter(x=>`${x.invoice_number||''} ${x.invoice_type} ${x.status}`.toLowerCase().includes(q));$('#viewBody').innerHTML=`<table class="data-table"><thead><tr><th>الرقم</th><th>النوع</th><th>التاريخ</th><th>الإجمالي</th><th>المدفوع</th><th>الحالة</th><th>إجراءات</th></tr></thead><tbody>${r.map(x=>`<tr><td>${escapeHTML(x.invoice_number||'مؤقت')}</td><td>${escapeHTML(x.invoice_type)}</td><td>${date(x.created_at)}</td><td>${money(x.total_amount)}</td><td>${money(x.total_paid)}</td><td>${escapeHTML(x.status)}</td><td class="action-cell"><button class="btn btn--outline action-btn" data-i="${x.id}">👁 التفاصيل</button><button class="btn btn--outline action-btn" data-p="${x.id}">🖨️ طباعة</button>${x.status==='active'&&x.invoice_type==='sale'&&App.currentUser&&(App.currentUser.role==='admin'||App.currentUser.canVoid)?`<button class="btn btn--danger action-btn" data-v="${x.id}">↩️ إلغاء</button>`:''}</td></tr>`).join('')}</tbody></table>`;$$('[data-i]').forEach(b=>invoiceDetail(b.dataset.i));$$('[data-p]').forEach(b=>invoicePrint(b.dataset.p));$$('[data-v]').forEach(b=>openVoidDialog(b.dataset.v));};render();bindToolbar('invoiceSearch',render,'الفواتير');$('#addBtn').onclick=render}
async function invoiceDetail(id){const d=await apiFetch('/pos/invoice/'+id);const i=d.invoice||d;openModal('تفاصيل الفاتورة',`<div class="stat-row"><div class="stat-card"><div>الرقم</div><div class="value">${escapeHTML(i.invoice_number||'مؤقت')}</div></div><div class="stat-card"><div>الإجمالي</div><div class="value">${money(i.total_amount)}</div></div></div><table class="data-table"><thead><tr><th>المنتج</th><th>الكمية</th><th>السعر</th><th>الإجمالي</th></tr></thead><tbody>${(d.items||i.items||[]).map(x=>`<tr><td>${escapeHTML(x.product_name||x.name||x.unit_name||'-')}</td><td>${money(x.quantity)}</td><td>${money(x.unit_price)}</td><td>${money(x.total_price)}</td></tr>`).join('')}</tbody></table>`)}
async function invoicePrint(id){const d=await apiFetch('/pos/invoice/'+id);const i=d.invoice||d;const items=d.items||[];printHTML('فاتورة '+(i.invoice_number||''),`<table><thead><tr><th>المنتج</th><th>الكمية</th><th>السعر</th><th>الإجمالي</th></tr></thead><tbody>${items.map(x=>`<tr><td>${escapeHTML(x.product_name||x.name||'-')}</td><td>${money(x.quantity)}</td><td>${money(x.unit_price)}</td><td>${money(x.total_price)}</td></tr>`).join('')}</tbody></table><h2>الإجمالي: ${money(i.total_amount)}</h2>`)}
async function openVoidDialog(id){const d=await apiFetch('/pos/void-otp',{method:'POST'});openModal('إلغاء الفاتورة',`<form id="entityForm"><p>رمز الأمان: <b>${escapeHTML(d.securityCode)}</b> — صالح ${d.ttlSeconds} ثانية</p><label>سبب الإلغاء<input name="reason" required minlength="3"></label><button class="btn btn--danger btn--block">تأكيد الإلغاء</button></form>`,b=>{$('#entityForm',b).onsubmit=async e=>{e.preventDefault();try{const f=new FormData(e.target);await apiFetch('/pos/void/'+id,{method:'POST',body:JSON.stringify({securityCode:d.securityCode,reason:f.get('reason')})});showToast('تم الإلغاء');closeModal();loadGenericView('invoices')}catch(err){showToast(err.message,'error')}}})}

async function renderReturns(c){c.innerHTML=shell('المرتجعات',toolbar('returnSearch','إنشاء مرتجع'));const data=await apiFetch('/pos/invoices?limit=200');const rows=(data.invoices||[]).filter(x=>x.invoice_type==='return');$('#viewBody').innerHTML=rows.length?`<table class="data-table"><thead><tr><th>الرقم</th><th>الأصل</th><th>التاريخ</th><th>الإجمالي</th><th>الحالة</th></tr></thead><tbody>${rows.map(x=>`<tr><td>${escapeHTML(x.invoice_number||'-')}</td><td>${escapeHTML(x.original_invoice_id||'-')}</td><td>${date(x.created_at)}</td><td>${money(x.total_amount)}</td><td>${escapeHTML(x.status)}</td></tr>`).join('')}</tbody></table>`:'<div class="empty-state">لا توجد مرتجعات بعد.</div>';$('#addBtn').onclick=()=>returnForm();$('#refreshBtn').onclick=()=>loadGenericView('returns');$('#exportBtn').onclick=()=>{const t=$('#viewBody table');if(t)exportTable(t,'المرتجعات')};$('#printBtn').onclick=()=>printHTML('المرتجعات',$('#viewBody').innerHTML)}
async function returnForm(){const invoices=(await apiFetch('/pos/invoices?limit=200')).invoices||[];const sales=invoices.filter(x=>x.invoice_type==='sale'&&x.status==='active');openModal('إنشاء مرتجع',`<form id="returnForm"><div class="form-grid"><label>الفاتورة الأصلية<select name="invoiceId" id="returnInvoice">${sales.map(x=>`<option value="${x.id}">${escapeHTML(x.invoice_number||x.id)} — ${money(x.total_amount)}</option>`).join('')}</select></label><label>السبب<input name="reason"></label></div><div id="returnItems" class="form-card">اختر الفاتورة...</div><button class="btn btn--success btn--block">↩️ حفظ المرتجع</button></form>`,async b=>{const load=async()=>{const id=$('#returnInvoice',b).value;if(!id)return;const d=await apiFetch('/pos/invoice/'+id);$('#returnItems',b).innerHTML=(d.items||[]).map(x=>`<label style="display:flex;gap:10px;align-items:center;margin:8px 0"><input type="number" min="0" max="${x.quantity}" step="0.001" data-item="${x.id}" value="0"><span>${escapeHTML(x.product_name||x.name||'-')} — مباع ${x.quantity}</span></label>`).join('')};$('#returnInvoice',b).onchange=load;await load();$('#returnForm',b).onsubmit=async e=>{e.preventDefault();const items=$$('[data-item]',b).map(x=>({invoiceItemId:x.dataset.item,quantity:Number(x.value)})).filter(x=>x.quantity>0);if(!items.length){showToast('حدد كمية مرتجع','error');return;}const shift=(await apiFetch('/shifts/current')).shift;if(!shift){showToast('افتح وردية أولًا','error');return;}try{await apiFetch('/pos/return',{method:'POST',body:JSON.stringify({originalInvoiceId:$('#returnInvoice',b).value,terminalId:localStorage.getItem('terminal_id')||'terminal-web',localSequence:Number(localStorage.getItem('local_sequence_counter')||1),shiftId:shift.id,items,reason:$('[name=reason]',b).value})});showToast('تم إنشاء المرتجع');closeModal();loadGenericView('returns')}catch(err){showToast(err.message,'error')}}})}

async function renderReports(c){c.innerHTML=shell('التقارير',`<select id="reportCurrency"><option>YER</option><option>SAR</option><option>USD</option></select><button class="btn btn--primary" id="loadReportsBtn">📊 تحديث التقارير</button><button class="btn btn--outline" id="printBtn">🖨️ طباعة</button>`);const load=async()=>{const cur=$('#reportCurrency').value;const [s,p,inv,cd,sd,pm,tp,cat]=await Promise.all([apiFetch('/reports/sales?currency='+cur),apiFetch('/reports/profit?currency='+cur),apiFetch('/reports/inventory?currency='+cur),apiFetch('/reports/customer-debts?currency='+cur),apiFetch('/reports/supplier-debts?currency='+cur),apiFetch('/reports/payment-methods-summary?currency='+cur),apiFetch('/reports/top-products?currency='+cur),apiFetch('/reports/sales-by-category?currency='+cur)]);$('#viewBody').innerHTML=`<div class="stat-row"><div class="stat-card">المبيعات<div class="value">${money(s.totalSales)}</div></div><div class="stat-card">الفواتير<div class="value">${s.totalInvoices}</div></div><div class="stat-card">الربح الإجمالي<div class="value">${money(p.grossProfit)}</div></div><div class="stat-card">قيمة المخزون<div class="value">${money(inv.report.total_value)}</div></div></div><h3>المبيعات</h3><table class="data-table"><thead><tr><th>اليوم</th><th>الفواتير</th><th>الإجمالي</th></tr></thead><tbody>${s.report.map(r=>`<tr><td>${date(r.day)}</td><td>${r.invoices_count}</td><td>${money(r.total)}</td></tr>`).join('')}</tbody></table><h3>أعلى المنتجات</h3><table class="data-table"><thead><tr><th>المنتج</th><th>الكمية</th><th>الإيراد</th></tr></thead><tbody>${tp.report.map(r=>`<tr><td>${escapeHTML(r.name)}</td><td>${money(r.qty)}</td><td>${money(r.revenue)}</td></tr>`).join('')}</tbody></table><h3>ديون العملاء</h3><table class="data-table"><thead><tr><th>العميل</th><th>الرصيد</th></tr></thead><tbody>${cd.report.map(r=>`<tr><td>${escapeHTML(r.name)}</td><td>${money(r.balance)}</td></tr>`).join('')}</tbody></table><h3>ديون الموردين</h3><table class="data-table"><thead><tr><th>المورد</th><th>الرصيد</th></tr></thead><tbody>${sd.report.map(r=>`<tr><td>${escapeHTML(r.name)}</td><td>${money(r.balance)}</td></tr>`).join('')}</tbody></table><h3>وسائل الدفع</h3><table class="data-table"><thead><tr><th>الوسيلة</th><th>الإجمالي</th></tr></thead><tbody>${pm.report.map(r=>`<tr><td>${escapeHTML(r.name)}</td><td>${money(r.total)}</td></tr>`).join('')}</tbody></table>`};$('#loadReportsBtn').onclick=load;$('#printBtn').onclick=()=>printHTML('التقارير',$('#viewBody').innerHTML);await load()}

async function renderShifts(c){c.innerHTML=shell('الورديات',toolbar('shiftSearch','فتح وردية'));const [cur,list]=await Promise.all([apiFetch('/shifts/current'),apiFetch('/shifts?limit=100')]);$('#viewBody').innerHTML=`<div class="stat-row"><div class="stat-card">الحالة<div class="value">${cur.shift?'مفتوحة':'مغلقة'}</div></div>${cur.shift?`<div class="stat-card">الافتتاح<div class="value">${money(cur.shift.opening_balance)}</div></div><div class="stat-card"><button class="btn btn--danger btn--block" id="closeShiftAction">🔒 إغلاق الوردية</button></div>`:''}</div><table class="data-table"><thead><tr><th>المستخدم</th><th>البداية</th><th>النهاية</th><th>الافتتاح</th><th>الإغلاق</th><th>الحالة</th><th>إجراءات</th></tr></thead><tbody>${(list.shifts||[]).map(s=>`<tr><td>${escapeHTML(s.user_name)}</td><td>${date(s.started_at)}</td><td>${date(s.ended_at)}</td><td>${money(s.opening_balance)}</td><td>${money(s.closing_balance)}</td><td>${escapeHTML(s.status)}</td><td><button class="btn btn--outline action-btn" data-summary="${s.id}">📊 ملخص</button></td></tr>`).join('')}</tbody></table>`;$('#addBtn').onclick=()=>shiftOpenForm();$('#refreshBtn').onclick=()=>loadGenericView('shifts');$('#exportBtn').onclick=()=>exportTable($('#viewBody table'),'الورديات');$('#printBtn').onclick=()=>printHTML('الورديات',$('#viewBody').innerHTML);$('#closeShiftAction')?.addEventListener('click',()=>shiftCloseForm(cur.shift));$$('[data-summary]').forEach(b=>shiftSummary(b.dataset.summary));}
function shiftOpenForm(){openModal('فتح وردية',`<form id="entityForm"><label>رصيد الافتتاح<input name="openingBalance" type="number" min="0" step="0.01" value="0" required></label><button class="btn btn--success btn--block">فتح الوردية</button></form>`,b=>{$('#entityForm',b).onsubmit=async e=>{e.preventDefault();try{const f=new FormData(e.target);await apiFetch('/shifts/open',{method:'POST',body:JSON.stringify({openingBalance:Number(f.get('openingBalance'))})});showToast('تم فتح الوردية');closeModal();loadGenericView('shifts')}catch(err){showToast(err.message,'error')}}})}
function shiftCloseForm(s){openModal('إغلاق الوردية',`<form id="entityForm"><label>رصيد الإغلاق الفعلي<input name="closingBalance" type="number" min="0" step="0.01" required></label><button class="btn btn--danger btn--block">إغلاق</button></form>`,b=>{$('#entityForm',b).onsubmit=async e=>{e.preventDefault();try{const f=new FormData(e.target);await apiFetch('/shifts/'+s.id+'/close',{method:'POST',body:JSON.stringify({closingBalance:Number(f.get('closingBalance'))})});showToast('تم إغلاق الوردية');closeModal();loadGenericView('shifts')}catch(err){showToast(err.message,'error')}}})}
async function shiftSummary(id){const d=await apiFetch('/reports/shift-summary/'+id);openModal('ملخص الوردية',`<div class="stat-row"><div class="stat-card">الافتتاح<div class="value">${money(d.shift?.opening_balance)}</div></div><div class="stat-card">السحوبات<div class="value">${money(d.drawer?.withdrawals)}</div></div><div class="stat-card">الإيداعات<div class="value">${money(d.drawer?.deposits)}</div></div></div>`)}

async function renderExpenses(c){c.innerHTML=shell('المصروفات',toolbar('expenseSearch','إضافة مصروف'));const d=await apiFetch('/accounting/expenses?limit=200');const rows=d.expenses||[];const render=()=>{const q=$('#expenseSearch').value.trim().toLowerCase();const r=rows.filter(x=>`${x.description||''} ${x.expense_type}`.toLowerCase().includes(q));$('#viewBody').innerHTML=`<table class="data-table"><thead><tr><th>التاريخ</th><th>النوع</th><th>الوصف</th><th>المبلغ</th><th>المسجل</th></tr></thead><tbody>${r.map(x=>`<tr><td>${escapeHTML(x.expense_date)}</td><td>${escapeHTML(x.expense_type)}</td><td>${escapeHTML(x.description||'-')}</td><td>${money(x.amount)}</td><td>${escapeHTML(x.full_name||'-')}</td></tr>`).join('')}</tbody></table>`};render();bindToolbar('expenseSearch',render,'المصروفات');$('#addBtn').onclick=()=>expenseForm()}
async function expenseForm(){const pm=await apiFetch('/payment-methods');const shift=(await apiFetch('/shifts/current')).shift;openModal('إضافة مصروف',`<form id="entityForm"><div class="form-grid"><label>النوع<select name="expenseType"><option value="operational">تشغيلي</option><option value="personal">شخصي</option><option value="damage">تلف</option><option value="other">أخرى</option></select></label><label>المبلغ<input name="amount" type="number" min="0.01" step="0.01" required></label><label>وسيلة الدفع<select name="paymentMethodId">${pm.paymentMethods.filter(x=>x.type!=='credit').map(x=>`<option value="${x.id}">${escapeHTML(x.name)}</option>`).join('')}</select></label><label>التاريخ<input name="expenseDate" type="date"></label><label>الوردية<select name="shiftId"><option value="">بدون</option>${shift?`<option value="${shift.id}">الوردية الحالية</option>`:''}</select></label><label>الوصف<input name="description"></label></div><button class="btn btn--success btn--block">💾 تسجيل المصروف</button></form>`,b=>{$('#entityForm',b).onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target);try{await apiFetch('/accounting/expenses',{method:'POST',body:JSON.stringify({expenseType:f.get('expenseType'),amount:Number(f.get('amount')),paymentMethodId:f.get('paymentMethodId'),expenseDate:f.get('expenseDate')||null,shiftId:f.get('shiftId')||null,description:f.get('description')})});showToast('تم تسجيل المصروف');closeModal();loadGenericView('expenses')}catch(err){showToast(err.message,'error')}}})}

async function renderPaymentMethods(c){c.innerHTML=shell('وسائل الدفع',toolbar('pmSearch','إضافة وسيلة دفع'));const d=await apiFetch('/payment-methods');const rows=d.paymentMethods||[];const render=()=>{const q=$('#pmSearch').value.trim().toLowerCase();const r=rows.filter(x=>`${x.name} ${x.type}`.toLowerCase().includes(q));$('#viewBody').innerHTML=`<table class="data-table"><thead><tr><th>الأيقونة</th><th>الاسم</th><th>النوع</th><th>مرجع إلزامي</th><th>إجراءات</th></tr></thead><tbody>${r.map(x=>`<tr><td>${escapeHTML(x.icon||'💳')}</td><td>${escapeHTML(x.name)}</td><td>${escapeHTML(x.type)}</td><td>${x.requires_reference?'نعم':'لا'}</td><td><button class="btn btn--primary action-btn" data-e="${x.id}">✏️ تعديل</button><button class="btn btn--danger action-btn" data-d="${x.id}">🗑 تعطيل</button></td></tr>`).join('')}</tbody></table>`;$$('[data-e]').forEach(b=>b.onclick=()=>paymentForm(rows.find(x=>x.id===b.dataset.e)));$$('[data-d]').forEach(b=>b.onclick=async()=>{if(!confirm('تعطيل وسيلة الدفع؟'))return;try{await apiFetch('/payment-methods/'+b.dataset.d,{method:'DELETE'});showToast('تم التعطيل');loadGenericView('paymentMethods')}catch(e){showToast(e.message,'error')}})};render();bindToolbar('pmSearch',render,'وسائل الدفع');$('#addBtn').onclick=()=>paymentForm(null)}
function paymentForm(x){x=x||{};openModal(x.id?'تعديل وسيلة الدفع':'إضافة وسيلة دفع',`<form id="entityForm"><div class="form-grid"><label>الاسم<input name="name" required value="${escapeHTML(x.name)}"></label><label>النوع<select name="type"><option value="cash">نقدي</option><option value="wallet">محفظة</option><option value="bank">حوالة/بنك</option><option value="credit">آجل</option><option value="other">أخرى</option></select></label><label>الأيقونة<input name="icon" value="${escapeHTML(x.icon||'💳')}"></label><label><span>يتطلب رقم مرجع</span><input name="requiresReference" type="checkbox" ${x.requires_reference?'checked':''}></label></div><button class="btn btn--success btn--block">💾 حفظ</button></form>`,b=>{$('[name=type]',b).value=x.type||'cash';$('#entityForm',b).onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target),body={name:f.get('name'),type:f.get('type'),icon:f.get('icon'),requiresReference:f.get('requiresReference')==='on'};try{await apiFetch(x.id?'/payment-methods/'+x.id:'/payment-methods',{method:x.id?'PUT':'POST',body:JSON.stringify(body)});showToast('تم الحفظ');closeModal();loadGenericView('paymentMethods')}catch(err){showToast(err.message,'error')}}})}

async function renderAccounting(c){c.innerHTML=shell('المحاسبة',`<button class="btn btn--primary" id="trialBtn">⚖️ ميزان المراجعة</button><button class="btn btn--outline" id="incomeBtn">📈 قائمة الدخل</button><button class="btn btn--outline" id="balanceBtn">🏦 الميزانية العمومية</button><button class="btn btn--outline" id="accountsBtn">📚 دليل الحسابات</button><button class="btn btn--outline" id="printBtn">🖨️ طباعة</button>`);const load=async()=>{const [t,i,b,a]=await Promise.all([apiFetch('/accounting/trial-balance'),apiFetch('/accounting/income-statement'),apiFetch('/accounting/balance-sheet'),apiFetch('/accounting/accounts')]);$('#viewBody').innerHTML=`<div class="stat-row"><div class="stat-card">مدين<div class="value">${money(t.totals.debit)}</div></div><div class="stat-card">دائن<div class="value">${money(t.totals.credit)}</div></div><div class="stat-card">صافي الدخل<div class="value">${money(i.netIncome)}</div></div></div><h3>ميزان المراجعة</h3><table class="data-table"><thead><tr><th>الحساب</th><th>الاسم</th><th>مدين</th><th>دائن</th></tr></thead><tbody>${t.accounts.map(x=>`<tr><td>${escapeHTML(x.code)}</td><td>${escapeHTML(x.name)}</td><td>${money(x.debit)}</td><td>${money(x.credit)}</td></tr>`).join('')}</tbody></table><h3>قائمة الدخل</h3><p>الإيرادات: <b>${money(i.revenue)}</b> — المصروفات: <b>${money(i.expenses)}</b> — صافي الدخل: <b>${money(i.netIncome)}</b></p><h3>الميزانية العمومية</h3><table class="data-table"><thead><tr><th>الحساب</th><th>النوع</th><th>مدين</th><th>دائن</th></tr></thead><tbody>${b.lines.map(x=>`<tr><td>${escapeHTML(x.code)} ${escapeHTML(x.name)}</td><td>${escapeHTML(x.account_type)}</td><td>${money(x.debit)}</td><td>${money(x.credit)}</td></tr>`).join('')}</tbody></table>`};await load();$('#trialBtn').onclick=load;$('#incomeBtn').onclick=load;$('#balanceBtn').onclick=load;$('#accountsBtn').onclick=async()=>{const d=await apiFetch('/accounting/accounts');openModal('دليل الحسابات',`<table class="data-table"><thead><tr><th>الكود</th><th>الحساب</th><th>النوع</th></tr></thead><tbody>${d.accounts.map(x=>`<tr><td>${escapeHTML(x.code)}</td><td>${escapeHTML(x.name)}</td><td>${escapeHTML(x.account_type)}</td></tr>`).join('')}</tbody></table>`)};$('#printBtn').onclick=()=>printHTML('المحاسبة',$('#viewBody').innerHTML)}
async function renderLedger(c){c.innerHTML=shell('دفتر الأستاذ',`<input id="ledgerAccount" class="search-input" placeholder="كود الحساب اختياري مثل 1110"><button class="btn btn--primary" id="ledgerLoad">🔎 عرض</button><button class="btn btn--outline" id="ledgerPrint">🖨️ طباعة</button><button class="btn btn--outline" id="ledgerExport">📥 CSV</button>`);const load=async()=>{const q=$('#ledgerAccount').value.trim();const d=await apiFetch('/accounting/ledger?limit=500'+(q?'&accountCode='+encodeURIComponent(q):''));$('#viewBody').innerHTML=`<table class="data-table"><thead><tr><th>القيد</th><th>التاريخ</th><th>الحساب</th><th>الوصف</th><th>مدين</th><th>دائن</th></tr></thead><tbody>${d.ledger.map(x=>`<tr><td>${escapeHTML(x.entry_number)}</td><td>${escapeHTML(x.entry_date)}</td><td>${escapeHTML(x.code)} — ${escapeHTML(x.name)}</td><td>${escapeHTML(x.description||x.line_description||'')}</td><td>${money(x.debit)}</td><td>${money(x.credit)}</td></tr>`).join('')}</tbody></table>`};await load();$('#ledgerLoad').onclick=load;$('#ledgerPrint').onclick=()=>printHTML('دفتر الأستاذ',$('#viewBody').innerHTML);$('#ledgerExport').onclick=()=>exportTable($('#viewBody table'),'دفتر_الأستاذ')}
async function renderDrawer(c){c.innerHTML=shell('الخرج اليومي',toolbar('drawerSearch','تسجيل حركة نقدية'));const shift=(await apiFetch('/shifts/current')).shift;const d=await apiFetch('/accounting/cash-drawer'+(shift?'?shiftId='+shift.id:''));const rows=d.transactions||[];const render=()=>{const q=$('#drawerSearch').value.trim().toLowerCase();const r=rows.filter(x=>`${x.type} ${x.reason}`.toLowerCase().includes(q));$('#viewBody').innerHTML=`<table class="data-table"><thead><tr><th>التاريخ</th><th>النوع</th><th>المبلغ</th><th>السبب</th><th>المستخدم</th></tr></thead><tbody>${r.map(x=>`<tr><td>${date(x.created_at)}</td><td>${x.type==='withdrawal'?'سحب':'إيداع'}</td><td>${money(x.amount)}</td><td>${escapeHTML(x.reason)}</td><td>${escapeHTML(x.full_name||'-')}</td></tr>`).join('')}</tbody></table>`};render();bindToolbar('drawerSearch',render,'الخرج اليومي');$('#addBtn').onclick=()=>drawerForm(shift)}
function drawerForm(shift){if(!shift){showToast('افتح وردية أولًا','error');return}openModal('تسجيل حركة نقدية',`<form id="entityForm"><div class="form-grid"><label>النوع<select name="type"><option value="withdrawal">سحب</option><option value="deposit">إيداع</option></select></label><label>المبلغ<input name="amount" type="number" min="0.01" step="0.01" required></label><label>السبب<input name="reason" required minlength="2"></label></div><button class="btn btn--success btn--block">💵 حفظ</button></form>`,b=>{$('#entityForm',b).onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target);try{await apiFetch('/accounting/cash-drawer',{method:'POST',body:JSON.stringify({shiftId:shift.id,type:f.get('type'),amount:Number(f.get('amount')),reason:f.get('reason'),approvedBy:null})});showToast('تم تسجيل الحركة');closeModal();loadGenericView('drawer')}catch(err){showToast(err.message,'error')}}})}

async function renderPurchases(c){c.innerHTML=shell('المشتريات',toolbar('purchaseSearch','إنشاء أمر شراء'));const d=await apiFetch('/suppliers/purchase-orders');const rows=d.purchaseOrders||[];const render=()=>{const q=$('#purchaseSearch').value.trim().toLowerCase();const r=rows.filter(x=>`${x.order_number} ${x.supplier_name}`.toLowerCase().includes(q));$('#viewBody').innerHTML=`<table class="data-table"><thead><tr><th>الرقم</th><th>المورد</th><th>التاريخ</th><th>الحالة</th><th>الإجمالي</th><th>إجراءات</th></tr></thead><tbody>${r.map(x=>`<tr><td>${escapeHTML(x.order_number)}</td><td>${escapeHTML(x.supplier_name)}</td><td>${date(x.created_at)}</td><td>${escapeHTML(x.status)}</td><td>${money(x.total_amount)}</td><td class="action-cell"><button class="btn btn--outline action-btn" data-p="${x.id}">👁 تفاصيل</button>${['ordered','partially_received'].includes(x.status)?`<button class="btn btn--success action-btn" data-r="${x.id}">📥 استلام</button>`:''}</td></tr>`).join('')}</tbody></table>`;$$('[data-p]').forEach(b=>purchaseDetail(b.dataset.p));$$('[data-r]').forEach(b=>purchaseReceive(b.dataset.r))};render();bindToolbar('purchaseSearch',render,'المشتريات');$('#addBtn').onclick=()=>purchaseForm()}
async function purchaseForm(){const [sup,prods]=await Promise.all([apiFetch('/suppliers?limit=200'),apiFetch('/products?limit=200')]);openModal('إنشاء أمر شراء',`<form id="entityForm"><div class="form-grid"><label>المورد<select name="supplierId">${sup.suppliers.map(s=>`<option value="${s.id}">${escapeHTML(s.name)}</option>`).join('')}</select></label><label style="grid-column:1/-1">ملاحظات<input name="notes"></label></div><h4>بنود الشراء</h4><div id="poItems"></div><button type="button" class="btn btn--outline" id="addPoItem">➕ إضافة بند</button><button class="btn btn--success btn--block" style="margin-top:12px">💾 إنشاء الأمر</button></form>`,b=>{const add=()=>{const row=document.createElement('div');row.className='form-grid';row.innerHTML=`<label>المنتج<select name="productId">${prods.products.map(p=>`<option value="${p.id}">${escapeHTML(p.name)}</option>`).join('')}</select></label><label>الكمية<input name="quantity" type="number" min="0.001" step="0.001" required></label><label>السعر<input name="unitPrice" type="number" min="0" step="0.01" required></label>`;$('#poItems',b).appendChild(row)};$('#addPoItem',b).onclick=add;add();$('#entityForm',b).onsubmit=async e=>{e.preventDefault();const rows=$$('#poItems .form-grid',b);const items=rows.map(r=>({productId:$('[name=productId]',r).value,quantity:Number($('[name=quantity]',r).value),unitPrice:Number($('[name=unitPrice]',r).value),unitId:null,taxId:null}));try{await apiFetch('/suppliers/purchase-orders',{method:'POST',body:JSON.stringify({supplierId:$('[name=supplierId]',b).value,notes:$('[name=notes]',b).value,items})});showToast('تم إنشاء أمر الشراء');closeModal();loadGenericView('purchases')}catch(err){showToast(err.message,'error')}}})}
async function purchaseDetail(id){const d=await apiFetch('/suppliers/purchase-orders/'+id);openModal('تفاصيل أمر الشراء',`<p>المورد: ${escapeHTML(d.purchaseOrder.supplier_id)}</p><table class="data-table"><thead><tr><th>المنتج</th><th>الكمية</th><th>السعر</th><th>الإجمالي</th></tr></thead><tbody>${d.items.map(x=>`<tr><td>${escapeHTML(x.product_name)}</td><td>${money(x.quantity)}</td><td>${money(x.unit_price)}</td><td>${money(x.total_amount)}</td></tr>`).join('')}</tbody></table>`)}
async function purchaseReceive(id){if(!confirm('استلام جميع بنود أمر الشراء؟'))return;try{await apiFetch('/suppliers/purchase-orders/'+id+'/receive',{method:'POST'});showToast('تم استلام أمر الشراء');loadGenericView('purchases')}catch(e){showToast(e.message,'error')}}

async function renderSettings(c){const d=await apiFetch('/accounting/settings').catch(()=>({settings:{}}));const cur=await apiFetch('/accounting/currencies').catch(()=>({currencies:[],rates:[]}));c.innerHTML=shell('الإعدادات',`<button class="btn btn--primary" id="saveSettings">💾 حفظ إعدادات المتجر</button><button class="btn btn--outline" id="setup2fa">🔐 إعداد 2FA</button>`);$('#viewBody').innerHTML=`<div class="form-card"><div class="form-grid"><label>رقم التسجيل الضريبي<input id="taxReg" value="${escapeHTML(d.settings.tax_registration_number||'')}"></label><label>العملة الأساسية<select id="defaultCurrency">${(cur.currencies||[{code:'YER'},{code:'SAR'},{code:'USD'}]).map(x=>`<option value="${x.code}">${x.code}</option>`).join('')}</select></label><label>الصوت<input id="soundOn" type="checkbox" ${localStorage.getItem('sound_enabled')!=='false'?'checked':''}></label><label>مستوى الصوت<input id="volume" type="range" min="0" max="1" step=".05" value="${localStorage.getItem('sound_volume')||.2}"></label><label>الوضع السريع<input id="scanOnly" type="checkbox"></label></div></div><div class="form-card"><h3>الضرائب</h3><div id="taxesBox">جاري التحميل...</div><button class="btn btn--primary" id="addTax">➕ إضافة ضريبة</button></div><div class="form-card"><h3>أسعار الصرف</h3><table class="data-table"><thead><tr><th>من</th><th>إلى</th><th>السعر</th><th>التاريخ</th></tr></thead><tbody>${(cur.rates||[]).map(r=>`<tr><td>${escapeHTML(r.from_currency)}</td><td>${escapeHTML(r.to_currency)}</td><td>${money(r.rate)}</td><td>${date(r.effective_at)}</td></tr>`).join('')}</tbody></table><button class="btn btn--primary" id="addRate">➕ إضافة سعر صرف</button></div>`;$('#defaultCurrency').value=d.settings.default_currency||'YER';$('#saveSettings').onclick=async()=>{try{await apiFetch('/accounting/settings',{method:'PUT',body:JSON.stringify({tax_registration_number:$('#taxReg').value,default_currency:$('#defaultCurrency').value})});localStorage.setItem('sound_enabled',$('#soundOn').checked?'true':'false');localStorage.setItem('sound_volume',$('#volume').value);document.body.classList.toggle('scan-only-mode',$('#scanOnly').checked);showToast('تم حفظ الإعدادات')}catch(e){showToast(e.message,'error')}};$('#setup2fa').onclick=async()=>{try{const x=await apiFetch('/auth/2fa/setup',{method:'POST'});openModal('إعداد التوثيق الثنائي',`<p>استخدم هذا الرابط في تطبيق المصادقة:</p><textarea style="width:100%;min-height:120px">${escapeHTML(x.otpauthUrl)}</textarea><p>بعد إدخاله، استخدم شاشة تسجيل الدخول لإدخال الرمز.</p>`)}catch(e){showToast(e.message,'error')}};$('#addRate').onclick=()=>rateForm();const taxes=await apiFetch('/accounting/taxes');$('#taxesBox').innerHTML=`<table class="data-table"><thead><tr><th>الاسم</th><th>النسبة</th><th>النوع</th><th>الحالة</th><th>إجراء</th></tr></thead><tbody>${(taxes.taxes||[]).map(t=>`<tr><td>${escapeHTML(t.name)}</td><td>${money(t.rate)}</td><td>${escapeHTML(t.type)}</td><td>${t.is_active?'نشطة':'متوقفة'}</td><td><button class="btn btn--primary action-btn" data-tax="${t.id}">✏️ تعديل</button></td></tr>`).join('')}</tbody></table>`;$$('[data-tax]').forEach(b=>b.onclick=()=>taxForm(taxes.taxes.find(x=>x.id===b.dataset.tax)));$('#addTax').onclick=()=>taxForm(null)}

function taxForm(x){x=x||{};openModal(x.id?'تعديل ضريبة':'إضافة ضريبة',`<form id="entityForm"><div class="form-grid"><label>الاسم<input name="name" required value="${escapeHTML(x.name)}"></label><label>النسبة<input name="rate" type="number" min="0" max="100" step="0.01" value="${x.rate??0}"></label><label>النوع<select name="type"><option value="percentage">نسبة مئوية</option><option value="fixed">ثابتة</option></select></label><label>نشطة<input name="isActive" type="checkbox" ${x.is_active!==false?'checked':''}></label></div><button class="btn btn--success btn--block">💾 حفظ الضريبة</button></form>`,b=>{$('[name=type]',b).value=x.type||'percentage';$('#entityForm',b).onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target);try{await apiFetch(x.id?'/accounting/taxes/'+x.id:'/accounting/taxes',{method:x.id?'PUT':'POST',body:JSON.stringify({name:f.get('name'),rate:Number(f.get('rate')),type:f.get('type'),isActive:f.get('isActive')==='on',accountId:null})});showToast('تم حفظ الضريبة');closeModal();loadGenericView('settings')}catch(err){showToast(err.message,'error')}}})}
function rateForm(){openModal('إضافة سعر صرف',`<form id="entityForm"><div class="form-grid"><label>من<input name="fromCurrency" value="USD" required></label><label>إلى<input name="toCurrency" value="YER" required></label><label>السعر<input name="rate" type="number" step="0.01" min="0.01" required></label></div><button class="btn btn--success btn--block">💱 حفظ السعر</button></form>`,b=>{$('#entityForm',b).onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target);try{await apiFetch('/accounting/currencies/rates',{method:'POST',body:JSON.stringify({fromCurrency:f.get('fromCurrency'),toCurrency:f.get('toCurrency'),rate:Number(f.get('rate'))})});showToast('تمت إضافة سعر الصرف');closeModal();loadGenericView('settings')}catch(err){showToast(err.message,'error')}}})}

function startStatusPolling(){updateInternetStatusBadge();addEventListener('online',updateInternetStatusBadge);addEventListener('offline',updateInternetStatusBadge);checkServerStatus();setInterval(checkServerStatus,15000)}
function updateInternetStatusBadge(){App.state.internetOnline=navigator.onLine;const e=$('#internetStatusBadge');e.classList.toggle('online',navigator.onLine);e.classList.toggle('offline',!navigator.onLine);e.innerHTML=`الإنترنت: <b>${navigator.onLine?'متصل ✅':'غير متصل ❌'}</b>`}
async function checkServerStatus(){const e=$('#serverStatusBadge');try{const r=await fetch('/api/health',{credentials:'include'});App.state.serverOnline=r.ok;e.classList.toggle('online',r.ok);e.classList.toggle('offline',!r.ok);e.innerHTML=`خادم الفرع: <b>${r.ok?'متصل ✅':'غير متصل ❌'}</b>`;window.OfflineSync?.setServerStatus(r.ok)}catch(err){App.state.serverOnline=false;e.classList.add('offline');e.classList.remove('online');e.innerHTML='خادم الفرع: <b>غير متصل ❌</b>';window.OfflineSync?.setServerStatus(false)}}

// HID barcode scanner
(()=>{let buffer='',last=0;document.addEventListener('keydown',e=>{const now=Date.now(),gap=now-last;last=now;if(e.key==='Enter'){if(buffer.length>=4){window.POS?.handleBarcodeScan(buffer);buffer=''}return}if(e.key.length===1){if(gap>50&&document.activeElement?.tagName==='INPUT'&&document.activeElement.id!=='posSearchInput'){buffer='';return}buffer+=e.key;if(buffer.length>64)buffer=buffer.slice(-64)}})})();

document.addEventListener('DOMContentLoaded',()=>{ if('serviceWorker' in navigator) navigator.serviceWorker.register('/sw.js').catch(()=>{}); $('#loginForm').addEventListener('submit',handleLogin);$('#logoutBtn').addEventListener('click',handleLogout);$('#themeToggleBtn').addEventListener('click',()=>{const dark=document.documentElement.dataset.theme==='dark';document.documentElement.dataset.theme=dark?'':'dark';localStorage.setItem('theme',dark?'light':'dark')});$$('.tab').forEach(t=>t.addEventListener('click',()=>switchView(t.dataset.view)));$('#drilldownCloseBtn').addEventListener('click',closeModal);$('#drilldownModal').addEventListener('click',e=>{if(e.target.id==='drilldownModal')closeModal()});const theme=localStorage.getItem('theme');if(theme==='dark')document.documentElement.dataset.theme='dark';});
